// AgentServiceServer is the server API for AgentService service.
// All implementations must embed UnimplementedAgentServiceServer
// for forward compatibility.
//
// AgentService is implemented by pillar-agent (gRPC server, storage node) and
// called by pillar-controller (gRPC client, Kubernetes cluster).
//
// All RPCs are idempotent — the controller may safely retry on any transient
// error.
type AgentServiceServer interface {
	// GetCapabilities returns the backend types and network protocols that this
	// agent supports.  Called during PillarAgent reconciliation to populate
	// status.capabilities and status.discoveredPools.
	GetCapabilities(context.Context, *GetCapabilitiesRequest) (*GetCapabilitiesResponse, error)
	// GetCapacity returns the current storage capacity of a specific pool.
	// Used to populate PillarStore.status.capacity.
	GetCapacity(context.Context, *GetCapacityRequest) (*GetCapacityResponse, error)
	// ListVolumes returns all volumes (backend resources) currently known by the
	// agent for a given pool.  Used for drift detection and recovery push.
	ListVolumes(context.Context, *ListVolumesRequest) (*ListVolumesResponse, error)
	// ListExports returns all currently active network exports (protocol target
	// entries) for a given pool.  Paired with ListVolumes for full state audit.
	ListExports(context.Context, *ListExportsRequest) (*ListExportsResponse, error)
	// HealthCheck returns the liveness and readiness status of the agent process
	// and its subsystems (ZFS kernel module, NVMe-oF configfs, etc.).
	// The controller uses this RPC to gate reconciliation and update
	// PillarAgent.status.conditions.
	HealthCheck(context.Context, *HealthCheckRequest) (*HealthCheckResponse, error)
	// CreateVolume creates the backend storage resource (e.g. ZFS zvol, LVM LV)
	// on the storage node.  This is the first step in the CreateVolume flow.
	//
	// Idempotent: if the volume already exists with the same parameters the
	// agent MUST return success.
	CreateVolume(context.Context, *CreateVolumeRequest) (*CreateVolumeResponse, error)
	// InspectImport resolves an existing filesystem source and validates its
	// native identity, exact effective quota, and configured placement read-only.
	// The controller calls it before reserving the backing resource.
	InspectImport(context.Context, *InspectImportRequest) (*InspectImportResponse, error)
	// ImportVolume adopts an already-existing backend storage resource into a
	// volume lifecycle instead of creating one.  It backs the CSI CreateVolume
	// path of a PersistentVolumeClaim that carries the
	// "pillar-csi.bhyoo.com/import-zvol" or "pillar-csi.bhyoo.com/import-lv"
	// annotation.
	//
	// Import is strictly read-only on the backend: the agent MUST refuse
	// (FAILED_PRECONDITION or INVALID_ARGUMENT) when the resolved volume_id
	// does not name an existing resource of the backend's volume type inside
	// its configured layout, when that resource is still in use on the storage
	// node (a target backstore, an nvmet namespace, a mount or an exclusive
	// device claim), or when capacity_bytes exceeds the resource's current
	// size.  It must never create or modify the resource.  ZFS zvol and LVM
	// backends implement it; filesystem backends implement it only for
	// filesystem adoption, which instead carries a pinned native identity and
	// requires an exact quota bound; other backends return UNIMPLEMENTED.
	//
	// LVM imports require expected_lvm_source and are pinned durably to that
	// identity and to preserve_original: a later import of the same volume_id
	// naming a different source, or downgrading a preserving adoption, is
	// refused with FAILED_PRECONDITION.
	//
	// Idempotent: repeated calls for the same volume_id return the same
	// device path and capacity.  The request is fenced like CreateVolume.
	ImportVolume(context.Context, *ImportVolumeRequest) (*ImportVolumeResponse, error)
	// InspectVolume reports what the storage node observes about a backend
	// resource and the agent's own record of it: LVM identity and layout,
	// filesystem signature, local consumers, the agent's configured exports
	// and the durable fence mark (including a pinned import source).
	//
	// Strictly read-only and unfenced: it never activates, mounts, modifies or
	// persists anything, never compares or admits a lifecycle, and never
	// infers ownership.  Only BACKEND_TYPE_LVM is supported; other backends
	// return UNIMPLEMENTED.  A corrupt fence mark returns INTERNAL.
	InspectVolume(context.Context, *InspectVolumeRequest) (*InspectVolumeResponse, error)
	// DeleteVolume destroys the backend storage resource.  The export MUST have
	// been removed (UnexportVolume) before calling this RPC; the agent will
	// return FAILED_PRECONDITION otherwise.
	//
	// Idempotent: if the volume does not exist, the agent MUST return success.
	DeleteVolume(context.Context, *DeleteVolumeRequest) (*DeleteVolumeResponse, error)
	// ExpandVolume resizes the backend storage resource to at least
	// requested_bytes.  The agent returns the actual allocated size.
	ExpandVolume(context.Context, *ExpandVolumeRequest) (*ExpandVolumeResponse, error)
	// ReleaseVolume ends a volume lifecycle's ownership of volume_id without
	// touching the backend resource.  It retires a lifecycle whose backend
	// volume it must not destroy — an import that was never durably adopted —
	// so the pre-existing resource is never destroyed, resized or modified.
	//
	// When the fence's lifecycle owns the volume ID, the agent removes the
	// lifecycle's network export (like UnexportVolume) and records the
	// lifecycle as ended.  When another lifecycle owns it, or no lifecycle
	// does, the agent only records the fence's lifecycle as retired and leaves
	// the other lifecycle's resources untouched.  Afterwards every mutating
	// request carrying the released lifecycle's token (including a delayed
	// ImportVolume) is rejected with FAILED_PRECONDITION, while a new
	// lifecycle may still import or create the volume ID.
	//
	// Idempotent: releasing an already released lifecycle returns success.
	ReleaseVolume(context.Context, *ReleaseVolumeRequest) (*ReleaseVolumeResponse, error)
	// TransferVolumeOwnership atomically transfers ownership of an adopted
	// backend resource from a retired lifecycle to a new one.  It is the
	// recovery path for a PillarVolumeState that was adopted (ImportVolume)
	// but whose controller record was lost before the adoption was durable:
	// instead of deleting the pre-existing resource, an operator-authorised
	// transfer moves the durable fence mark to the new lifecycle.
	//
	// The request carries no FencingToken: authority is cryptographic, not
	// caller-asserted.  The agent accepts the transfer only when ALL of:
	//   - snapshot.signature verifies under the agent's own configured server
	//     TLS identity (the snapshot is self-attestation produced while the
	//     agent was healthy — never an mTLS peer assertion);
	//   - authorization.signature verifies under an operator public key from
	//     the configured --recovery-trust-anchor file, is within
	//     issued_at/expires_at, and its snapshot_digest equals the digest of
	//     the presented snapshot;
	//   - the mark's current uid/generation equal old_volume_uid/old_generation
	//     exactly and the mark's pinned LVM source equals lvm_source;
	//   - under the per-volume lock the device is provably idle (no exports,
	//     no ACL entries, no local consumers, O_EXCL claim free) — a stale or
	//     replayed snapshot cannot override a live observation;
	//   - authorization.new_volume_uid/new_generation differ from every
	//     lifecycle already recorded in the mark.
	//
	// One atomic mark write then records the new uid/generation, retires the
	// old uid, and pins the preserve policy and the authorization digest.
	// If the rename/fsync outcome is uncertain the agent returns
	// TRANSFER_OUTCOME_UNKNOWN and performs no rollback.  Retrying the exact
	// same snapshot+authorization is idempotent; retrying with a different
	// destination uid/generation or a different digest is refused with
	// FAILED_PRECONDITION.  When no --recovery-trust-anchor is configured the
	// agent fails closed with UNAVAILABLE.
	TransferVolumeOwnership(context.Context, *TransferVolumeOwnershipRequest) (*TransferVolumeOwnershipResponse, error)
	// ExportVolume creates the network-protocol target entry that exposes the
	// already-created volume to the network (e.g. adds an NVMe-oF subsystem +
	// namespace, or an iSCSI LUN, or an NFS export).
	//
	// Idempotent: if the export already exists with the same parameters the
	// agent MUST return the existing ExportInfo and success.
	ExportVolume(context.Context, *ExportVolumeRequest) (*ExportVolumeResponse, error)
	// UnexportVolume removes the network-protocol target entry (e.g. deletes the
	// NVMe-oF subsystem or unexports the NFS path).  Initiator ACL entries are
	// removed automatically.
	//
	// Idempotent: if the export does not exist, the agent MUST return success.
	UnexportVolume(context.Context, *UnexportVolumeRequest) (*UnexportVolumeResponse, error)
	// AllowInitiator grants network access to a single initiator for an already-
	// exported volume.  Corresponds to CSI ControllerPublishVolume.
	//
	// The meaning of initiator_id depends on the protocol:
	//   NVMe-oF TCP → host NQN   (added to allowed_hosts)
	//   iSCSI       → IQN        (added to LIO ACL)
	//   NFS         → client IP  (added to /etc/exports client list)
	//
	// Idempotent: if the ACL entry already exists the agent MUST return success.
	AllowInitiator(context.Context, *AllowInitiatorRequest) (*AllowInitiatorResponse, error)
	// DenyInitiator revokes network access for a single initiator.  Corresponds
	// to CSI ControllerUnpublishVolume.
	//
	// Idempotent: if the ACL entry does not exist the agent MUST return success.
	DenyInitiator(context.Context, *DenyInitiatorRequest) (*DenyInitiatorResponse, error)
	// SetLocalAttach switches a volume's network export between serving remote
	// initiators and being fenced for a direct attach on the storage node
	// itself.  Corresponds to CSI ControllerPublishVolume when the publishing
	// node is the storage node (local = true) or when a later publish goes to
	// a remote node after a local attach (local = false).
	//
	// local = true:  the agent stops the export from serving I/O to every
	//                remote initiator (NVMe-oF TCP: namespace enable = 0) and
	//                returns the backend device path the storage node mounts.
	// local = false: the agent refuses with FAILED_PRECONDITION while the
	//                backend device is still held exclusively on the storage
	//                node (a local mount or device-mapper claim is still
	//                present), and otherwise re-enables the export.
	//
	// Idempotent in both directions.
	SetLocalAttach(context.Context, *SetLocalAttachRequest) (*SetLocalAttachResponse, error)
	// SendVolume streams the raw binary content of a backend volume to the
	// caller.  Intended for cross-node volume migration and offline backup.
	// The canonical implementation for ZFS backends is `zfs send`; for LVM it
	// is `dd if=<lv>`.
	//
	// The volume SHOULD be quiesced (UnexportVolume called) before streaming to
	// avoid data inconsistency.  The controller is responsible for quiescing.
	//
	// The response is a server-side stream of SendVolumeChunk messages.  The
	// first chunk (sequence == 0) carries the total_bytes field; subsequent
	// chunks carry only data and sequence.  The final chunk sets eof = true.
	SendVolume(*SendVolumeRequest, grpc.ServerStreamingServer[SendVolumeChunk]) error
	// ReceiveVolume receives a binary data stream from the caller and writes it
	// into a pre-existing backend volume.  The mirror operation of SendVolume.
	// The canonical implementation for ZFS backends is `zfs receive`; for LVM
	// it is `dd of=<lv>`.
	//
	// The destination volume MUST already exist (CreateVolume) and MUST NOT be
	// exported (UnexportVolume must have been called) when this RPC is invoked.
	//
	// The request is a client-side stream of ReceiveVolumeChunk messages.  The
	// first chunk (sequence == 0) carries volume_id and backend_type; subsequent
	// chunks carry only data and sequence.  The final chunk sets eof = true.
	ReceiveVolume(grpc.ClientStreamingServer[ReceiveVolumeChunk, ReceiveVolumeResponse]) error
	// ReconcileState converges the listed volumes to their desired exports and
	// ACLs.  The controller calls it level-triggered for every provisioned
	// volume (on volume/agent changes and periodically), so configfs state lost
	// to an agent restart, node reboot, or nvmet reload is re-created without a
	// dedicated restart signal.  Each volume carries its fencing token, so a
	// stale controller's reconcile is rejected per volume.  The agent returns
	// per-item results.
	//
	// The agent MUST NOT return an error if configfs entries already exist — it
	// reconciles to the desired state.  Targets of volumes that are not listed
	// are never modified.
	//
	// Export restore after a process start: every subsystem of a storage node
	// shares a few NVMe/TCP ports, and nvmet starts listening on a port when the
	// first subsystem is linked to it.  A host that reconnects to a listening
	// port for a subsystem that is not linked yet (or not fully configured) is
	// rejected with a do-not-retry status and deletes its controller.  The agent
	// therefore starts with HealthCheckResponse.export_restore_pending set and
	// rejects export-creating RPCs (ExportVolume, AllowInitiator, and a
	// ReconcileState without complete) with UNAVAILABLE until it has processed
	// a request with complete=true.  For every request the agent first
	// configures every listed export fully (subsystem, ACL, namespace identity,
	// enabled namespace) and only then links them to their ports.
	ReconcileState(context.Context, *ReconcileStateRequest) (*ReconcileStateResponse, error)
	// Drain stops the agent from accepting new mutating RPCs and waits until
	// all in-flight per-target operations have released their locks.  After
	// Drain returns successfully the agent persists a state-flush marker so
	// the next restart can detect a clean shutdown.
	//
	// Idempotent: subsequent calls return was_already_drained=true and do not
	// re-block; they are safe to invoke from a preStop hook that may run more
	// than once.
	//
	// Once drained the agent will reject every other RPC with code
	// UNAVAILABLE until the process is restarted; Drain itself is always
	// accepted so that orchestrators can confirm the drained state.
	Drain(context.Context, *DrainRequest) (*DrainResponse, error)
	mustEmbedUnimplementedAgentServiceServer()
}

